import java.io.*;
import java.util.*;

public class HeightAllTheSame {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String[] vals = br.readLine().split(" ");
        long N = Long.parseLong(vals[0]);
        long M = Long.parseLong(vals[1]);
        long L = Long.parseLong(vals[2]);
        long R = Long.parseLong(vals[3]);

        long total = R - L + 1;
        long evenCount = total / 2 + (total % 2 == 0 && L % 2 == 0 ? 1 : 0);
        long oddCount = total - evenCount;

        long result;
        if ((N * M) % 2 == 1) {
            result = computePower(evenCount + oddCount, N * M);
        } else {
            result = (computePower(evenCount + oddCount, N * M) + computePower(evenCount - oddCount, N * M)) % mod;
            result = (result * modInverse(2)) % mod;
        }
        System.out.println(result);
    }

    static long mod = 998244353;

    static long modInverse(long x) {
        return computePower(x, mod - 2);
    }

    static long computePower(long base, long exp) {
        long res = 1;
        long b = base % mod;
        long e = exp;
        while (e > 0) {
            if ((e & 1) == 1) {
                res = (res * b) % mod;
            }
            b = (b * b) % mod;
            e >>= 1;
        }
        return res;
    }
}
